const sessionId = "session-1";

function proposalTab(type = "goal", title = "Goal Proposal"): SidePanelWorkspaceTab {
	return {
		id: `proposal:${type}`,
		kind: "proposal",
		title,
		label: "Goal",
		source: { type: "proposal", sessionId, proposalType: type as any },
		updatedAt: 1,
	};
}

function previewTab(entry = "index.html", version?: number): SidePanelWorkspaceTab {
	return {
		id: `preview:entry:${encodeURIComponent(entry)}${version ? `:v:${version}` : ""}`,
		kind: "preview",
		title: entry,
		label: entry,
		source: { type: "preview", sessionId, entry, ...(version ? { historical: true, version } : { live: true }) },
		updatedAt: 1,
	};
}

function contextTab(): SidePanelWorkspaceTab {
	return {
		id: "context",
		kind: "context",
		title: "Context",
		label: "Context",
		source: { type: "context", sessionId },
		updatedAt: 1,
	};
}

function reviewTab(reviewId = "review-1", title = "Review"): SidePanelWorkspaceTab {
	return {
		id: `review:${encodeURIComponent(reviewId)}`,
		kind: "review",
		title,
		label: title,
		source: { type: "review", sessionId, reviewId, title },
		updatedAt: 1,
	};
}

